"""Minimum Depth of Binary Tree — BFS stops at the first leaf.

DFS would explore the whole tree; a level-order scan returns as soon as it meets
a node with no children.

Time: O(n) worst case   Space: O(width)
"""
from collections import deque

if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def minDepth(self, root) -> int:
        if not root:
            return 0
        queue = deque([(root, 1)])
        while queue:
            node, depth = queue.popleft()
            if not node.left and not node.right:
                return depth
            if node.left:
                queue.append((node.left, depth + 1))
            if node.right:
                queue.append((node.right, depth + 1))
        return 0
